chrome.runtime.onInstalled.addListener(e=>{e.reason==="install"&&console.log("TRAZE Extension installed successfully.")});chrome.runtime.onMessage.addListener((e,a,s)=>{if(e.action==="OPEN_DASHBOARD"){let r=chrome.runtime.getURL("src/dashboard/dashboard.html");return chrome.tabs.create({url:r}),s({success:!0}),!0}if(e.action==="CLEAR_ACTIVE_SESSION")return chrome.storage.local.remove(["followtrace_current_analysis","followtrace_viewed_users","followtrace_review_statuses"]),s({success:!0}),!0});chrome.tabs.onRemoved.addListener(async()=>{try{let e=chrome.runtime.getURL("src/dashboard/dashboard.html");(await chrome.tabs.query({})).some(r=>r.url&&r.url.startsWith(e))||await chrome.storage.local.remove(["followtrace_current_analysis","followtrace_viewed_users","followtrace_review_statuses"])}catch(e){console.error("Error cleaning session on tab close:",e)}});
